// Produkt-Tour: drei Ansichten (Mitglied, Zustimmung, Kassier) mit Mockups
import Button from "@/components/ui/Button";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import Reveal from "@/components/ui/Reveal";
import { cn } from "@/components/ui/cn";
import { MockAbschluss, MockEnergieHeute, MockKassier, MockZustimmung } from "@/components/Portal/EG/Produkt/Mockups";
import { Haken } from "./teile";

const TOUR = [
  {
    id: "mitglied",
    eyebrow: "Für Mitglieder",
    titel: "Energie heute: Mitglieder sehen ihre Ersparnis, bevor sie fragen",
    text: "Das Dashboard zeigt den Energiefluss von den Anlagen der Region bis nach Hause, die Ersparnis aus Energiepreis, Netzentgelt und Abgabe und die grünen Stunden des Tages – mit einem Hinweis, wann sich Waschmaschine oder Wallbox lohnen.",
    punkte: ["Ersparnis getrennt nach Energie, Netz und Abgabe, als Schätzung gekennzeichnet", "Grüne Stunden aus Prognose und Messwerten – Empfehlung, keine Steuerung", "Belege, Preisblatt und eigene Daten an einem Ort"],
    bildText: "Beispielansicht Energie heute auf dem Handy, fiktive Werte: viel Gemeinschaftsstrom laut Prognose, Energiefluss von der Region über die Gemeinschaft Sonnenland nach Hause, 71,40 € Ersparnis in diesem Jahr, 38 % aus der Gemeinschaft und die grünen Stunden des Tages.",
    buehne: "from-sand-50 to-ov-50",
  },
  {
    id: "zustimmung",
    eyebrow: "Für neue Mitglieder",
    titel: "Damit keine Anmeldung verfällt: Countdown und Anleitung je Netzbetreiber",
    text: "Vergisst ein Mitglied die Zustimmung im Portal des Netzbetreibers, verfällt die Anmeldung nach zehn Werktagen. Unser Portal zählt die Tage herunter und erklärt jeden Klick für den jeweiligen Netzbetreiber – direkt nach dem Beitritt.",
    punkte: ["Status jeder Anmeldung Schritt für Schritt", "Fristring mit Datum, dringend ab sieben Tagen", "Anleitung je Netzbetreiber im Kontext des Zählpunkts"],
    bildText: "Beispielansicht Zustimmung beim Netzbetreiber, fiktive Werte: Fristring mit noch 6 von 10 Werktagen, als dringend markiert, Frist bis 14.10.; Anleitung in fünf Schritten, die ersten zwei erledigt (Kundenportal öffnen, Bereich Energiegemeinschaften wählen), jetzt an der Reihe: Anfrage der Gemeinschaft finden; danach Teilnahmefaktor prüfen und zustimmen.",
    buehne: "from-sand-50 to-ov-50",
  },
  {
    id: "kassier",
    eyebrow: "Für Kassa und Vorstand",
    titel: "Abrechnung als geführte Routine – mit Vier-Augen-Freigabe",
    text: "Vorschau berechnen, Veränderungen zum Vormonat sehen, als Kassier und Vorstand freigeben, versenden: Jeder Schritt hat einen klaren Status, jede Zahl einen Prüfpfad bis zum Viertelstundenwert.",
    punkte: ["Status-Pipeline je Periode, Vier-Augen-Freigabe mit Bestätigung", "Vergleich zum Vorzeitraum mit auffälligen Mitgliedern", "SEPA-Lastschrift und -Überweisung, Mahnwesen, Exporte für die Steuerberatung"],
    bildText: "Beispielansicht der Abrechnung Oktober, fiktive Werte: Status-Pipeline bei Schritt 5 von 6 (Versendet), 58 Rechnungen und 14 Gutschriften, drei auffällige Veränderungen zum September, geprüft vom Kassier und freigegeben vom Vorstand; Abschlussmeldung: 72 Belege versendet, Lastschrift am 05.11.",
    buehne: "from-sand-50 to-navy-50",
  },
];

/** Tour-Mockup je Ansicht – als Abbildung mit sichtbarer Kennzeichnung „fiktive Werte“ */
function TourBild({ t }) {
  if (t.id === "mitglied") {
    return (
      <MockEnergieHeute beschreibung={t.bildText} className="relative mx-auto w-full max-w-[300px]" />
    );
  }
  if (t.id === "zustimmung") {
    return (
      <MockZustimmung beschreibung={t.bildText} className="relative mx-auto w-full max-w-[460px]" />
    );
  }
  return (
    <div role="img" aria-label={t.bildText} className="relative mx-auto w-full max-w-[560px] sm:pb-8">
      <div aria-hidden="true">
        <MockKassier />
        {/* Mobil im Fluss, damit die Freigabe-Chips sichtbar bleiben; ab sm schwebend. Landet kurz nach dem Fenster. */}
        <Reveal dir="up" delay={450} className="relative z-10 -mt-3 ml-auto w-[88%] max-w-[300px] sm:absolute sm:-bottom-2 sm:-right-4 sm:mt-0 sm:w-[70%]">
          <MockAbschluss />
        </Reveal>
      </div>
    </div>
  );
}

export default function Tour() {
  return (
    <Section data-abschnitt="tour" tone="white" space="lg" id="produkt" className="scroll-mt-24">
      <SectionHeading eyebrow="Das Produkt" title="Drei Ansichten, ein Gedanke: niemand muss nachfragen" lead="So sieht die Plattform für Mitglieder, für die Zustimmung beim Netzbetreiber und für die Kassa aus. Alle Werte in den Ansichten sind Beispiele." className="mb-12 md:mb-16" />
      <div className="space-y-20 md:space-y-28">
        {TOUR.map((t, i) => (
          <div key={t.id} id={`produkt-${t.id}`} className="grid scroll-mt-24 items-center gap-10 lg:grid-cols-2 lg:gap-16">
            <Reveal dir={i % 2 ? "left" : "right"} className={cn("max-w-xl", i % 2 && "lg:order-2")}>
              <p className="ov-overline text-ink-500"><span className="text-ov-700">0{i + 1}</span> / 03 · {t.eyebrow}</p>
              <h3 className="ov-h3 mt-3 text-ink-900">{t.titel}</h3>
              <p className="ov-text mt-4 text-ink-600">{t.text}</p>
              <ul className="mt-6 space-y-2.5">
                {t.punkte.map((x) => <li key={x} className="ov-klein flex gap-2.5 text-ink-700"><Haken />{x}</li>)}
              </ul>
            </Reveal>
            <Reveal dir="scale" className={cn(i % 2 && "lg:order-1")}>
              <figure>
                <div className={cn("relative isolate flex min-h-[380px] items-center justify-center overflow-hidden rounded-[2.5rem] bg-gradient-to-br p-6 ring-1 ring-sand-200 md:min-h-[500px] md:p-10", t.buehne)}>
                  <div aria-hidden="true" className="ov-grid-bg-light absolute inset-0 -z-10" />
                  <div aria-hidden="true" className="absolute left-1/2 top-1/2 -z-10 h-72 w-72 -translate-x-1/2 -translate-y-1/2 rounded-full bg-ov-200/50 blur-3xl" />
                  <TourBild t={t} />
                </div>
                <figcaption className="mt-3 text-center text-[12.5px] text-ink-500">Beispielansicht mit fiktiven Werten</figcaption>
              </figure>
            </Reveal>
          </div>
        ))}
      </div>
      <Reveal className="mt-16 flex flex-col items-center justify-center gap-4 text-center sm:flex-row sm:text-left md:mt-20">
        <p className="ov-text text-ink-700">Möchten Sie die Ansichten mit Ihren eigenen Zahlen sehen?</p>
        <Button href="#anfrage" pfeil>Vorführung anfragen</Button>
      </Reveal>
    </Section>
  );
}
// Für Kassa und Vorstand
import { BadgeCheck, ClipboardList, FileSignature, HandCoins, ShieldCheck, Users } from "lucide-react";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import FeatureGrid from "@/components/ui/FeatureGrid";

/** Arbeitswerkzeuge für Kassa und Vorstand – nur Aussagen, die auch in Tour, Vergleich und FAQ stehen */
const VORSTAND = [
  { icon: Users, title: "Organe und Versammlungen", text: "Vereinsführung direkt in der Plattform: Organe, Versammlungen und Beschlüsse der Gemeinschaft an einem Ort." },
  { icon: BadgeCheck, title: "Vier-Augen-Freigabe", text: "Jede Abrechnung und Zahlung mit zwei Freigaben – Status je Periode und Vergleich zum Vorzeitraum." },
  { icon: HandCoins, title: "SEPA und Mahnwesen", text: "SEPA-Lastschrift und -Überweisung aus der Abrechnung heraus, Mahnwesen inklusive." },
  { icon: ClipboardList, title: "Umsatzsteuer-Sonderfälle", text: "Kleinunternehmer, Landwirt, Reverse Charge – die Fälle, die in Vereinen sonst von Hand laufen." },
  { icon: FileSignature, title: "Export für die Steuerberatung", text: "Exporte für die Steuerberatung, jede Zahl mit Prüfpfad bis zum Viertelstundenwert." },
  { icon: ShieldCheck, title: "Einzeleinsicht nur mit Zweck", text: "Vorstand und Kassa sehen standardmäßig Summen; eine Einzeleinsicht ist nur mit Zweck möglich und wird protokolliert." },
];

export default function Kassa() {
  return (
    <Section data-abschnitt="kassa" tone="sand" space="lg" id="kassa" className="scroll-mt-24">
      <SectionHeading eyebrow="Für Kassa und Vorstand" title="Der Verein läuft mit – nicht nebenher" lead="Die Arbeit, die in Vorständen die meiste Zeit kostet, an einem Ort: Vereinsführung, Freigaben, Zahlungsverkehr und Exporte." className="mb-10 md:mb-12" />
      <FeatureGrid items={VORSTAND} cols={3} />
    </Section>
  );
}
// Gemeinsame Helfer der Seite /energiegemeinschaften/software
import { Check } from "lucide-react";
import { cn } from "@/components/ui/cn";

/** Häkchen-Chip als Aufzählungszeichen (BadgeCheck bleibt der Vergleichstabelle vorbehalten) */
export function Haken({ dunkel = false }) {
  return (
    <span aria-hidden="true" className={cn("mt-[3px] flex h-4 w-4 shrink-0 items-center justify-center rounded-full", dunkel ? "bg-white/10 text-ov-300" : "bg-ov-100 text-ov-700")}>
      <Check className="h-2.5 w-2.5" strokeWidth={3} />
    </span>
  );
}
