/* ------------------------------------------------------------------
   DESIGN-TOKENS FÜR TAILWIND
   Gemessen standen auf der Startseite 9 verschiedene Schatten und
   3 verschiedene Animationskurven nebeneinander. Hier werden die
   Tailwind-Standards überschrieben, damit shadow-sm … shadow-2xl und
   alle transition-*-Klassen seitenweit dieselbe Handschrift tragen:
   weiche, mehrlagige Schatten statt eines harten Einzelschattens und
   eine Kurve, die zügig startet und ruhig ausläuft.
   ------------------------------------------------------------------ */
@theme {
  --default-transition-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  --default-transition-duration: 220ms;

  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.05), 0 1px 1px rgba(15, 23, 42, 0.03);
  --shadow: 0 1px 3px rgba(15, 23, 42, 0.06), 0 2px 6px -2px rgba(15, 23, 42, 0.06);
  --shadow-md: 0 2px 4px -1px rgba(15, 23, 42, 0.05), 0 6px 16px -4px rgba(15, 23, 42, 0.08);
  --shadow-lg: 0 4px 8px -2px rgba(15, 23, 42, 0.05), 0 14px 32px -8px rgba(15, 23, 42, 0.12);
  --shadow-xl: 0 8px 16px -4px rgba(15, 23, 42, 0.06), 0 24px 48px -12px rgba(15, 23, 42, 0.16);
  --shadow-2xl: 0 12px 24px -6px rgba(15, 23, 42, 0.08), 0 36px 72px -18px rgba(15, 23, 42, 0.22);

  /* ---------------- Ökovolt Design-System 2026 ---------------- */
  --font-sans: var(--font-inter), system-ui, "Segoe UI", Arial, sans-serif;
  --font-display: var(--font-manrope), var(--font-inter), system-ui, sans-serif;

  /* Markengrün als volle Skala (500 = #669933) */
  --color-ov-50: #f4f9ee;
  --color-ov-100: #e6f1d8;
  --color-ov-200: #cde3b1;
  --color-ov-300: #aed083;
  --color-ov-400: #8cba58;
  --color-ov-500: #669933;
  --color-ov-600: #558227;
  --color-ov-700: #436621;
  --color-ov-800: #37521e;
  --color-ov-900: #2f461c;

  /* Markenblau als Skala (700 = #003473) */
  --color-navy-50: #eef4fb;
  --color-navy-100: #d9e6f5;
  --color-navy-200: #b2cbe9;
  --color-navy-300: #7fa7d6;
  --color-navy-400: #4a7cbd;
  --color-navy-500: #1f5aa1;
  --color-navy-600: #0b4488;
  --color-navy-700: #003473;
  --color-navy-800: #03285a;
  --color-navy-900: #041d42;
  --color-navy-950: #03122b;

  /* Neutrale Töne mit leicht kühlem Stich – passend zum Navy */
  --color-ink-50: #f7f8fa;
  --color-ink-100: #eef0f4;
  --color-ink-200: #dfe3ea;
  --color-ink-300: #c4cad5;
  /* 2.0 Kontrast (UX-Audit P0): ink-400 war #97a0b0 (2,6:1 auf Weiß) und wurde an
     ~190 Stellen als Text genutzt → jetzt ≥ 4,5:1 auf Weiß/Sand/ink-50.
     ink-500 rückt nach (war #6b7486). Dekoratives Mittelgrau: ink-300 bzw. ink-350. */
  --color-ink-350: #8a93a4; /* 3,1:1 – Feldrahmen, Grafik-Grenzen (WCAG 1.4.11) */
  --color-ink-400: #687183; /* 4,9:1 auf Weiß, 4,6:1 auf ink-50 */
  --color-ink-500: #5a6375; /* 6,0:1 auf Weiß, 5,3:1 auf ink-100 */
  --color-ink-600: #4e5667;
  --color-ink-700: #394050;
  --color-ink-800: #252b37;
  --color-ink-900: #151a24;

  /* Sonnen-Akzent: nur sparsam (Live-Daten, Highlights) */
  --color-sun-300: #ffd873;
  --color-sun-400: #ffc53d;
  --color-sun-500: #f5a70f;

  /* Warmer Papierton für ruhige Flächen */
  --color-sand-50: #fbfaf6;
  --color-sand-100: #f5f3ea;

  --radius-4xl: 2rem;
  --radius-5xl: 2.5rem;

  --animate-ov-float: ov-float 7s ease-in-out infinite;
  --animate-ov-marquee: ov-marquee 40s linear infinite;
  --animate-ov-pulse-dot: ov-pulse-dot 2s cubic-bezier(0.22, 1, 0.36, 1) infinite;
  --animate-ov-shimmer: ov-shimmer 2.4s linear infinite;

  /* ================= DESIGN-SYSTEM 2.0 (docs/DESIGN.md) ================= */

  /* Skalen ergänzt (bestehende Stufen unverändert) */
  --color-sun-50: #fffaeb;
  --color-sun-100: #fff1c9;
  --color-sun-200: #ffe49a;
  --color-sun-600: #c98500;
  --color-sun-700: #8a5a00;
  --color-sand-200: #ebe7d8;
  --color-ink-950: #0b0f17;

  /* Semantik – nur Verweise auf Markenskalen, plus ein gedämpftes Rot
     (Fehler müssen eindeutig sein; kein Markengrün für „Fehler“). */
  --color-success-50: var(--color-ov-50);
  --color-success-100: var(--color-ov-100);
  --color-success-200: var(--color-ov-200);
  --color-success-500: var(--color-ov-500);
  --color-success-600: var(--color-ov-600);
  --color-success-700: var(--color-ov-700);
  --color-success-800: var(--color-ov-800);
  --color-info-50: var(--color-navy-50);
  --color-info-100: var(--color-navy-100);
  --color-info-200: var(--color-navy-200);
  --color-info-500: var(--color-navy-500);
  --color-info-600: var(--color-navy-600);
  --color-info-700: var(--color-navy-700);
  --color-info-800: var(--color-navy-800);
  --color-warn-50: var(--color-sun-50);
  --color-warn-100: var(--color-sun-100);
  --color-warn-200: var(--color-sun-200);
  --color-warn-500: var(--color-sun-500);
  --color-warn-600: var(--color-sun-600);
  --color-warn-700: var(--color-sun-700);
  --color-warn-800: #6b4600;
  --color-danger-50: #fdf3f2;
  --color-danger-100: #fbe3e0;
  --color-danger-200: #f5c2bc;
  --color-danger-300: #e8806f;
  --color-danger-500: #d6463a;
  --color-danger-600: #b8352a;
  --color-danger-700: #962a21;
  --color-danger-800: #77231c;

  /* Elevation: 5 Stufen + farbige Schatten + Lichtkante für dunkle Flächen */
  --shadow-e1: 0 1px 2px rgba(3, 18, 43, 0.04), 0 1px 1px rgba(3, 18, 43, 0.02);
  --shadow-e2: 0 1px 2px rgba(3, 18, 43, 0.04), 0 4px 12px -4px rgba(3, 18, 43, 0.08);
  --shadow-e3: 0 2px 4px -1px rgba(3, 18, 43, 0.05), 0 12px 28px -10px rgba(3, 18, 43, 0.16);
  --shadow-e4: 0 4px 8px -2px rgba(3, 18, 43, 0.06), 0 24px 48px -16px rgba(3, 18, 43, 0.22);
  --shadow-e5: 0 8px 16px -4px rgba(3, 18, 43, 0.08), 0 40px 80px -24px rgba(3, 18, 43, 0.32);
  --shadow-gruen: 0 8px 24px -8px rgba(85, 130, 39, 0.55);
  --shadow-navy: 0 10px 30px -12px rgba(0, 52, 115, 0.55);
  --shadow-kante: inset 0 1px 0 rgba(255, 255, 255, 0.07);

  /* Kurven (als Utilities: ease-ov-out, ease-ov-in-out, ease-ov-feder, ease-ov-betont) */
  --ease-ov-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-ov-in-out: cubic-bezier(0.65, 0, 0.35, 1);
   profitieren sofort, ohne dass jede Komponente angefasst werden muss. */
h1, h2, h3, h4, .font-display {
  font-family: var(--font-display);
  letter-spacing: -0.015em;
}

/* Fluide Typografie – skaliert ohne Sprünge zwischen 360 und 1440 px. */
.ov-display {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(2.35rem, 1.45rem + 4vw, 4.75rem);
  line-height: 1.02;
  letter-spacing: -0.035em;
}
.ov-h1 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(2.1rem, 1.5rem + 2.7vw, 3.75rem);
  line-height: 1.06;
  letter-spacing: -0.03em;
}
.ov-h2 {
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(1.75rem, 1.3rem + 1.9vw, 3rem);
  line-height: 1.1;
  letter-spacing: -0.028em;
}
.ov-h3 {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(1.2rem, 1.05rem + 0.6vw, 1.5rem);
  line-height: 1.25;
  letter-spacing: -0.015em;
}
.ov-lead {
  font-size: clamp(1.05rem, 0.98rem + 0.35vw, 1.25rem);
  line-height: 1.65;
}

.ov-container {
  width: 100%;
  max-width: 80rem;
  margin-inline: auto;
  padding-inline: 1.25rem;
}
@media (min-width: 768px) { .ov-container { padding-inline: 2rem; } }

/* Grüner Verlaufstext für Schlüsselwörter in Headlines */
.ov-text-gradient {
  background: linear-gradient(100deg, #8cba58 0%, #669933 45%, #3f7a2a 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.ov-text-gradient-light {
  background: linear-gradient(100deg, #d9f0b8 0%, #aed083 50%, #ffd873 110%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* Feines Raster für dunkle Flächen */
.ov-grid-bg {
  background-image:
    linear-gradient(rgba(255,255,255,0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.045) 1px, transparent 1px);
  background-size: 56px 56px;
  mask-image: radial-gradient(ellipse at center, #000 30%, transparent 75%);
}
.ov-grid-bg-light {
  background-image:
    linear-gradient(rgba(0,52,115,0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0,52,115,0.05) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: radial-gradient(ellipse at top, #000 20%, transparent 70%);
}

/* Körnung gegen „Plastik-Look" auf großen Verläufen */
.ov-noise::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.06;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
}

/* Glas-Karte für Inhalte auf Bildern / dunklen Flächen */
.ov-glass {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  backdrop-filter: blur(16px) saturate(140%);
  -webkit-backdrop-filter: blur(16px) saturate(140%);
}

/* Karten mit Licht-Kante beim Hover */
/* 2.0: Schatten nicht mehr als box-shadow animiert, sondern über ein
   Pseudo-Element per opacity (wie .ov-lift). Karten mit overflow-hidden
   würden das Pseudo-Element abschneiden – dort steht der Schatten direkt
   am Element, ohne Übergang (nur die Bewegung animiert). */
.ov-card-hover {
  position: relative;
  isolation: isolate;
  transition: transform 350ms cubic-bezier(0.22, 1, 0.36, 1), border-color 350ms;
}
.ov-card-hover::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  box-shadow: 0 2px 6px -2px rgba(15, 23, 42, 0.06), 0 24px 48px -16px rgba(15, 23, 42, 0.18);
  opacity: 0;
  transition: opacity 350ms cubic-bezier(0.22, 1, 0.36, 1);
  pointer-events: none;
}
@media (hover: hover) {
  .ov-card-hover:hover::before { opacity: 1; }
  .ov-card-hover.overflow-hidden:hover {
    box-shadow: 0 2px 6px -2px rgba(15, 23, 42, 0.06), 0 24px 48px -16px rgba(15, 23, 42, 0.18);
  }
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .ov-card-hover:hover {
    transform: translateY(-4px);
  }
}

/* Reveal-Animation (gesteuert von <Reveal/>). Ohne JS bleibt alles sichtbar. */
.ov-reveal {
  /* 2.0: nur transform/opacity (kein filter: blur – teuer beim Scrollen) */
  transition:
    opacity 700ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 700ms cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--ov-delay, 0ms);
}
.js-ready .ov-reveal:not(.is-visible) {
  opacity: 0;
  transform: translate3d(0, 24px, 0);
  font-weight: 700;
  font-size: clamp(1.05rem, 1rem + 0.25vw, 1.2rem);
  line-height: 1.3;
  letter-spacing: -0.01em;
}
.ov-text { font-size: clamp(0.95rem, 0.92rem + 0.12vw, 1.0625rem); line-height: 1.65; }
.ov-klein { font-size: 0.875rem; line-height: 1.55; }
.ov-mikro { font-size: 0.78rem; line-height: 1.45; letter-spacing: 0.005em; }
.ov-overline {
  font-size: 0.75rem;
  font-weight: 700;
  line-height: 1.4;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

/* Zahlen-Typo: tabellarisch, Display-Schrift, enge Laufweite.
   Einheit (span.ov-einheit) kleiner und leichter, damit die Zahl führt. */
.ov-kpi, .ov-kpi-l, .ov-kpi-xl {
  font-family: var(--font-display);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
  letter-spacing: -0.03em;
  line-height: 1;
}
.ov-kpi { font-size: clamp(1.5rem, 1.3rem + 0.8vw, 2rem); }
.ov-kpi-l { font-size: clamp(2rem, 1.6rem + 1.6vw, 3rem); }
.ov-kpi-xl { font-size: clamp(2.6rem, 1.8rem + 3.4vw, 4.5rem); letter-spacing: -0.04em; }
.ov-einheit { font-size: 0.55em; font-weight: 700; letter-spacing: -0.01em; margin-left: 0.18em; opacity: 0.72; }

/* ---------- Flächen ---------- */
.ov-flaeche {
  background: #fff;
  border-radius: 1.5rem;
  box-shadow: var(--ov-e1), 0 0 0 1px rgba(223, 227, 234, 0.8);
}
.ov-flaeche-erhaben {
  background: #fff;
  border-radius: 1.5rem;
  box-shadow: var(--ov-e3), 0 0 0 1px rgba(223, 227, 234, 0.6);
}
.ov-flaeche-ruhig {
  background: var(--color-sand-50);
  border-radius: 1.5rem;
  box-shadow: 0 0 0 1px rgba(235, 231, 216, 0.9);
}
.ov-flaeche-dunkel {
  background: var(--ov-nacht-2);
  color: #fff;
  border-radius: 1.5rem;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.07), 0 0 0 1px var(--ov-nacht-linie);
}
/* Marken-Verläufe für Hero-Kacheln und „Nächster Schritt“ */
.ov-verlauf-nacht {
  background:
    radial-gradient(120% 80% at 0% 0%, rgba(102, 153, 51, 0.22), transparent 55%),
    radial-gradient(90% 70% at 100% 100%, rgba(31, 90, 161, 0.35), transparent 60%),
    var(--ov-nacht-1);
}
.ov-verlauf-gruen {
  background:
    radial-gradient(100% 90% at 100% 0%, rgba(174, 208, 131, 0.35), transparent 55%),
    linear-gradient(135deg, var(--color-ov-600), var(--color-ov-800));
}
/* Haarlinie, die zu den Rändern ausläuft */
.ov-trenner {
  height: 1px;
  border: 0;
  background: linear-gradient(90deg, transparent, var(--color-ink-200) 15%, var(--color-ink-200) 85%, transparent);
}

/* ---------- Motion-Muster ---------- */

/* Hover-Lift: Bewegung per transform, Schatten über Pseudo-Element per
   opacity (kein box-shadow-Repaint). Nicht mit .ov-noise kombinieren. */
.ov-lift {
  position: relative;
  isolation: isolate;
  transition: transform var(--ov-dauer-s) var(--ov-ease-out);
}
.ov-lift::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  box-shadow: var(--ov-e4);
  opacity: 0;
  transition: opacity var(--ov-dauer-m) var(--ov-ease-out);
  pointer-events: none;
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .ov-lift:hover { transform: translate3d(0, -3px, 0); }
}
@media (hover: hover) {
  .ov-lift:hover::before { opacity: 1; }
}
.ov-lift:focus-visible::before { opacity: 1; }

/* Press: kurzes Eindrücken bei allem Klickbaren */
.ov-press { transition: transform var(--ov-dauer-s) var(--ov-ease-out); }
@media (prefers-reduced-motion: no-preference) {
  .ov-press:active { transform: scale(0.975); transition-duration: 60ms; }
}

/* Stagger: Kinder erscheinen nacheinander, sobald der Elternblock sichtbar
   wird (RevealObserver setzt is-visible). Der Elternblock selbst bleibt
   stehen. Index automatisch bis 12 Kinder oder per style="--i: n". */
.ov-stagger > * {
  transition:
    opacity var(--ov-dauer-l) var(--ov-ease-out),
    transform var(--ov-dauer-l) var(--ov-ease-out);
  transition-delay: calc(var(--i, 0) * var(--ov-stagger) + var(--ov-delay, 0ms));
}
.ov-stagger > :nth-child(2) { --i: 1; }
import { cn } from "./cn";

/**
 * Einblenden beim Scrollen – ohne eigenen Client-Baustein.
 * Die Klasse `ov-reveal` wird global vom <RevealObserver/> beobachtet
 * (siehe LayoutWrapper). Ohne JavaScript bleibt der Inhalt sichtbar.
 *
 * dir: up (Standard) | left | right | scale
 */
export default function Reveal({ as: Tag = "div", delay = 0, dir, className, style, children, ...rest }) {
  return (
    <Tag
      // RevealObserver ergänzt `is-visible` am Client – auch in Bereichen, die
      // beim Streaming noch nicht hydriert sind. Diese Abweichung ist gewollt.
      suppressHydrationWarning
      className={cn("ov-reveal", className)}
      data-dir={dir}
      style={delay ? { "--ov-delay": `${delay}ms`, ...style } : style}
      {...rest}
    >
      {children}
    </Tag>
  );
}
import { cn } from "./cn";

const TOENE = {
  white: "bg-white text-ink-900",
  sand: "bg-sand-50 text-ink-900",
  ink: "bg-ink-50 text-ink-900",
  green: "bg-ov-50 text-ink-900",
  navy: "bg-navy-950 text-white",
};

const ABSTAENDE = {
  none: "",
  sm: "py-12 md:py-16",
  md: "py-16 md:py-24",
  lg: "py-20 md:py-32",
};

/**
 * Seitenabschnitt mit einheitlichem Rhythmus.
 * tone: white | sand | ink | green | navy
 * space: none | sm | md | lg
 */
export default function Section({
  tone = "white",
  space = "md",
  id,
  className,
  containerClassName,
  bare = false,
  as: Tag = "section",
  children,
  ...rest
}) {
  return (
    <Tag
      id={id}
      className={cn("relative", TOENE[tone], ABSTAENDE[space], className)}
      {...rest}
    >
      {bare ? children : <div className={cn("ov-container relative", containerClassName)}>{children}</div>}
    </Tag>
  );
}

export function Container({ className, children }) {
  return <div className={cn("ov-container", className)}>{children}</div>;
}
import { cn } from "./cn";
import Reveal from "./Reveal";

/**
 * Kleine Überzeile über Headlines.
 * Der Punkt sitzt in einer Box mit genau einer Zeilenhöhe – einzeilig mittig zum Text,
 * bei Umbruch mittig zur ersten Zeile.
 */
export function Eyebrow({ children, dark = false, className }) {
  return (
    <p
      className={cn(
        "inline-flex items-start gap-2 text-[12.5px] font-semibold uppercase leading-[1.5] tracking-[0.16em]",
        dark ? "text-ov-300" : "text-ov-700",
        className
      )}
    >
      <span aria-hidden="true" className="flex h-[1.5em] shrink-0 items-center">
        <span className={cn("h-1.5 w-1.5 rounded-full", dark ? "bg-ov-300" : "bg-ov-500")} />
      </span>
      <span>{children}</span>
    </p>
  );
}

/**
 * Überschriftenblock eines Abschnitts.
 * as: h1 | h2 | h3 – semantische Ebene; die Optik bleibt über `size` steuerbar.
 */
export default function SectionHeading({
  eyebrow,
  title,
  lead,
  align = "left",
  dark = false,
  as: Tag = "h2",
  size = "h2",
  className,
  children,
}) {
  const zentriert = align === "center";
  return (
    <Reveal
      className={cn(
        "max-w-3xl",
        zentriert && "mx-auto text-center",
        className
      )}
    >
      {eyebrow && (
        <Eyebrow dark={dark} className={cn("mb-4", zentriert && "justify-center")}>
          {eyebrow}
        </Eyebrow>
      )}
      <Tag
        className={cn(
          size === "display" ? "ov-display" : size === "h1" ? "ov-h1" : size === "h3" ? "ov-h3" : "ov-h2",
          dark ? "text-white" : "text-ink-900"
        )}
      >
        {title}
      </Tag>
      {lead && (
        <p className={cn("ov-lead mt-5", dark ? "text-white/70" : "text-ink-600", zentriert && "mx-auto max-w-2xl")}>
          {lead}
        </p>
      )}
      {children}
    </Reveal>
  );
}

import Link from "next/link";
import { ArrowRight, LoaderCircle } from "lucide-react";
import { cn } from "./cn";

const VARIANTEN = {
  primary:
    "bg-ov-600 text-white shadow-[0_8px_24px_-8px_rgba(102,153,51,0.65)] hover:bg-ov-700 hover:shadow-[0_12px_32px_-8px_rgba(102,153,51,0.75)]",
  navy: "bg-navy-700 text-white hover:bg-navy-800 shadow-[0_8px_24px_-10px_rgba(0,52,115,0.6)]",
  secondary:
